sn_aia_tool.script:
(function(inputs) {
// only string inputs are allowed 
// return outputs object where the keys in it are understandable by LLM
var outputPayload = {};
var getUR = new GlideRecord('sys_upgrade_history');
getUR.addQuery("to_version","CONTAINS",inputs.upgradeName.toString());
getUR.addQuery("upgrade_finished","!=","");
getUR.orderByDesc("sys_created_on");
getUR.query();
if(getUR.next())
{
    outputPayload = {
                "from_version": getUR.from_version.toString(),
                "to_version": getUR.to_version.toString(),
                "total_changes": parseInt(getUR.changes_processed),
                "changes_skipped": parseInt(getUR.changes_skipped),
                "started_on": getUR.upgrade_started.toString(),
                "finished_on": getUR.upgrade_finished.toString(),
                "upgrade_sysID": getUR.sys_id.toString()
            };
        return JSON.stringify(outputPayload);
}
else
    return "No record found";
})(inputs);
